client_script:
frappe.ready(function() {
    // Get flight parameter from URL
    const urlParams = new URLSearchParams(window.location.search);
    const flight = urlParams.get('flight');

    if (flight) {
        // Set the flight field
        frappe.web_form.set_value('flight', flight);

        // Fetch flight details and set price
        frappe.call({
            method: 'frappe.client.get',
            args: {
                doctype: 'Airplane Flight',
                name: flight
            },
            callback: function(r) {
                if (r.message) {
                    // Set flight price (you can set any default price here)
                    frappe.web_form.set_value('flight_price', 5000);

                    // Optionally set source and destination
                    frappe.web_form.set_value('source_airport', r.message.source_airport);
                    frappe.web_form.set_value('destination_airport', r.message.destination_airport);
                }
            }
        });
    }
});
